package com.example.tutorapp.network

/**
 * Central server configuration.
 *
 * Change SERVER_HOST and SERVER_PORT here and the whole app
 * (REST API + WebSocket + media URLs) will pick it up.
 *
 * For production, replace with BuildConfig fields generated by
 * Gradle build types / product flavors.
 */
object AppConfig {

    // ── Change this to match your backend ────────────────────────────────
    private const val SERVER_HOST = "eduvibe-backend-for-app-development.onrender.com"
    private const val SERVER_PORT = 443
    // ─────────────────────────────────────────────────────────────────────

    private const val BASE_URL_HTTP = "https://$SERVER_HOST"
    const val API_BASE              = "$BASE_URL_HTTP/api/v1/"
    const val MEDIA_BASE            = BASE_URL_HTTP

    /** WebSocket URL — token is appended as a query param at connect time. */
    fun wsUrl(): String = "wss://$SERVER_HOST/ws"
}